/**
 * Benchmarks Page — Word500 tab
 *
 * Pivot table (models × tests) with multi-unit cells (accuracy, completion
 * tokens, failure modes), model comparison with accuracy + token charts.
 *
 * Data: assets/data/word500.json (generated by tools/word500_ingest.mjs from
 * run directories under assets/data/<run_id>/).
 */
(async function () {
  "use strict";

  // ─── Data ────────────────────────────────────────────────────────────
  const scriptTag = document.currentScript;
  const dataUrl = scriptTag.dataset.word500Url || "/data/word500.json";
  const data = await fetch(dataUrl).then((r) => r.json());
  const runs = (data && data.runs) || [];
  if (runs.length === 0) return;

  // State
  let activeTests = new Set();
  // localStorage key for the saved test selection (see bench-state.js)
  const TEST_STATE_KEY = "word500.active-tests";
  // Tests selected by default on first visit (before the user makes their
  // own picks, which are then remembered): the three full-vision suites.
  const DEFAULT_ACTIVE_TESTS = ["SmokeWord500", "PokerWord500", "HoardWord500"];
  let modelFilter = "";
  let sortCol = "model";
  let sortDir = "asc";
  let sortMetric = "accuracy";
  let selectedModels = new Set();
  let compareMode = false;
  let accChart = null;
  let tokChart = null;
  const MAX_COMPARE = 4;
  const OVERALL = "__overall__";

  // ─── Merged view ─────────────────────────────────────────────────────
  // The table spans every run: union of models and union of tests. A model
  // that was run more than once shows the results from its newest run;
  // test order follows the newest run that contains each test.
  const runsNewestFirst = [...runs].sort((a, b) =>
    (b.run_id || "").localeCompare(a.run_id || "")
  );
  const modelRun = {}; // model -> run whose results it shows (newest wins)
  for (const r of runsNewestFirst) {
    for (const m of r.models) if (!(m in modelRun)) modelRun[m] = r;
  }
  const mergedTests = [];
  for (const r of runsNewestFirst) {
    for (const t of r.tests)
      if (!mergedTests.some((x) => x.name === t.name))
        mergedTests.push({ name: t.name, vision: !!t.vision, samples: t.samples });
  }
  const mergedRun = {
    models: Object.keys(modelRun),
    tests: mergedTests,
    results: Object.fromEntries(
      Object.keys(modelRun).map((m) => [m, modelRun[m].results[m]])
    ),
    overall: {
      n: Object.keys(modelRun).reduce((s, m) => {
        const agg = (modelRun[m].results[m] || {}).overall;
        return s + (agg && agg.n ? agg.n : 0);
      }, 0),
    },
  };
  const run = () => mergedRun;

  // ─── DOM refs ────────────────────────────────────────────────────────
  const $ = (s) => document.querySelector(s);
  const thead = $("#w500TableHead");
  const tbody = $("#w500TableBody");
  const testFilter = $("#w500TestFilter");
  const modelInput = $("#w500ModelFilter");
  const metricSelect = $("#w500SortMetric");
  const compareBtn = $("#w500CompareBtn");
  const backBtn = $("#w500BackBtn");
  const tableView = $("#w500TableView");
  const compareView = $("#w500CompareView");
  const noResults = $("#w500NoResults");
  const runMeta = $("#w500RunMeta");
  const compareHead = $("#w500CompareHead");
  const compareBody = $("#w500CompareBody");
  const compareModelsDiv = $("#w500CompareModels");

  // Shared modal (this script populates it for Word500 model links)
  const modal = $("#benchModelModal");
  const modalTitle = $("#benchModalTitle");
  const modalBody = $("#benchModalBody");
  const modalClose = $("#benchModalClose");

  // ─── Formatters ──────────────────────────────────────────────────────
  function esc(s) {
    const d = document.createElement("div");
    d.textContent = s == null ? "" : String(s);
    return d.innerHTML;
  }

  function fmtPct(v) {
    if (v == null) return "—";
    return (v * 100).toFixed(1) + "%";
  }

  function fmtTok(v) {
    if (v == null) return "—";
    if (v >= 1000) {
      const k = (v / 1000).toFixed(1).replace(/\.0$/, "");
      return k + "k";
    }
    return String(Math.round(v));
  }

  function fmtLat(v) {
    if (v == null) return "—";
    if (v < 60) return v.toFixed(1) + "s";
    const m = Math.floor(v / 60);
    return m + "m " + Math.round(v % 60) + "s";
  }

  function fmtDate(d) {
    if (!d) return "—";
    return new Date(d).toLocaleDateString("en-US", {
      month: "short",
      day: "numeric",
      year: "numeric",
    });
  }

  // Short display names for test suites. Raw names remain the data keys
  // (sorting, filtering, aggregation) — this map only affects what users see.
  const TEST_DISPLAY_NAMES = {
    SMOKEWORD500: "SMOKE",
    POKERWORD500: "POKER",
    HOARDWORD500: "HOARD",
    "SMOKEWORD500-NOVISION": "SMOKE-NV",
    "POKERWORD500-NOVISION": "POKER-NV",
    "HOARDWORD500-NOVISION": "HOARD-NV",
  };
  function shortName(name) {
    return TEST_DISPLAY_NAMES[String(name).toUpperCase()] || name;
  }

  // ─── Aggregates ──────────────────────────────────────────────────────
  function getAgg(model, test) {
    const m = run().results[model];
    if (!m) return null;
    if (test === OVERALL) return m.overall;
    return m.tests[test] || null;
  }

  function metricValue(agg, metric) {
    if (!agg || !agg.n) return null;
    switch (metric) {
      case "accuracy":
        return agg.correct / agg.n;
      case "tokens":
        return agg.tokens.avg;
      case "loop_aborts":
        return agg.loop_aborts;
      case "truncated":
        return agg.truncated;
      default:
        return null;
    }
  }

  // "Lower is better" for everything except accuracy
  function defaultDirFor(col) {
    if (col === "model") return "asc";
    return sortMetric === "accuracy" ? "desc" : "asc";
  }

  function sortModels(models) {
    const dir = sortDir === "asc" ? 1 : -1;
    return models.slice().sort((a, b) => {
      let va, vb;
      if (sortCol === "model") {
        va = a.toLowerCase();
        vb = b.toLowerCase();
      } else {
        va = metricValue(getAgg(a, sortCol), sortMetric);
        vb = metricValue(getAgg(b, sortCol), sortMetric);
        if (va == null && vb == null) return 0;
        if (va == null) return 1; // missing data always sorts last
        if (vb == null) return -1;
      }
      return va < vb ? -dir : va > vb ? dir : 0;
    });
  }

  // ─── Run bar ─────────────────────────────────────────────────────────
  // The table merges models from every run, so the bar summarizes the
  // run configs across all runs: a single value when every run agrees,
  // otherwise the range of values seen.
  function renderRunBar() {
    const cfgs = runs.map((r) => r.config || {});
    const distinct = (fn) => [...new Set(cfgs.map(fn).filter((v) => v != null))];
    const parts = [];
    const r = run();
    if (r.overall && r.overall.n) parts.push(r.overall.n + " samples");
    const maxTok = distinct((c) => c.max_tokens);
    if (maxTok.length === 1) parts.push("max " + fmtTok(maxTok[0]) + " tokens");
    else if (maxTok.length > 1) parts.push("max tokens " + maxTok.map(fmtTok).join("–"));
    const temps = distinct((c) => c.temperature);
    if (temps.length === 1) parts.push("temp " + temps[0]);
    else if (temps.length > 1) parts.push("temp " + temps.join("–"));
    const loopCfgs = cfgs.filter((c) => c.loop_abort);
    if (cfgs.length > 0 && loopCfgs.length === cfgs.length) {
      const reps = [
        ...new Set(loopCfgs.map((c) => (c.loop_abort_repeats != null ? c.loop_abort_repeats : "?"))),
      ];
      parts.push("loop abort after " + reps.join("–") + " repeats");
    } else if (loopCfgs.length > 0) {
      parts.push("loop abort (some runs only)");
    }
    runMeta.textContent = parts.join(" · ");
  }

  // Default selection: the DEFAULT list limited to what's currently
  // available. If every default name is gone (renames/removals), fall back
  // to all available.
  function defaultTests(available) {
    const set = new Set(available);
    const kept = DEFAULT_ACTIVE_TESTS.filter((n) => set.has(n));
    return kept.length > 0 ? kept : [...available];
  }

  // ─── Filters ─────────────────────────────────────────────────────────
  function renderTestFilters() {
    const tests = run().tests;
    const names = tests.map((t) => t.name);
    // Restore the user's saved selection (survives reloads). Falls back
    // to the default selection when nothing usable is saved.
    const restored = window.BenchState.restoreSelection(TEST_STATE_KEY, names);
    activeTests.clear();
    (restored || defaultTests(names)).forEach((n) => activeTests.add(n));
    testFilter.innerHTML = tests
      .map(
        (t) =>
          `<label class="bench-bench-label" title="${
            t.vision
              ? "Board state provided as an image"
              : "Board state included as text in the prompt"
          }"><input type="checkbox" value="${esc(t.name)}" ${activeTests.has(t.name) ? "checked" : ""}> ${esc(shortName(t.name))}</label>`
      )
      .join("");
  }

  testFilter.addEventListener("change", (e) => {
    if (e.target.type !== "checkbox") return;
    if (e.target.checked) activeTests.add(e.target.value);
    else activeTests.delete(e.target.value);
    window.BenchState.saveSelection(TEST_STATE_KEY, activeTests);
    renderTable();
    if (compareMode) {
      renderCompare();
      renderCharts();
    }
  });

  let filterTimeout;
  modelInput.addEventListener("input", () => {
    clearTimeout(filterTimeout);
    filterTimeout = setTimeout(() => {
      modelFilter = modelInput.value;
      renderTable();
    }, 200);
  });

  metricSelect.addEventListener("change", () => {
    sortMetric = metricSelect.value;
    // Re-rank the whole table by the new priority (Overall column); clicking
    // a column header still sorts that column by the chosen metric.
    sortCol = OVERALL;
    sortDir = defaultDirFor(OVERALL);
    renderTable();
  });

  // ─── Table cells ─────────────────────────────────────────────────────
  function flagChips(agg) {
    const chips = [];
    if (agg.truncated > 0)
      chips.push(
        '<span class="w500-flag w500-flag-trunc" title="Hit the max-token limit: reasoning ran on without a detectable loop pattern">⚠ ' +
          agg.truncated +
          "</span>"
      );
    if (agg.loop_aborts > 0)
      chips.push(
        '<span class="w500-flag w500-flag-loop" title="Doom-loop detected in the reasoning, request aborted">⛔ ' +
          agg.loop_aborts +
          "</span>"
      );
    if (agg.errors > 0)
      chips.push(
        '<span class="w500-flag w500-flag-err" title="Request errors">✖ ' + agg.errors + "</span>"
      );
    return chips;
  }

  function cellInner(agg) {
    const chips = flagChips(agg);
    return (
      `<div class="w500-acc">${agg.correct}/${agg.n}<span class="w500-pct"> (${fmtPct(agg.correct / agg.n)})</span></div>` +
      `<div class="w500-tok" title="Average completion tokens per sample">${
        agg.tokens.estimated > 0 ? "≈ " : ""
      }${fmtTok(agg.tokens.avg)} tok</div>` +
      (chips.length ? `<div class="w500-flags">${chips.join("")}</div>` : "")
    );
  }

  function cellHtml(agg, winner) {
    if (!agg || !agg.n) return '<td class="bench-no-data">—</td>';
    return `<td class="w500-cell${winner ? " w500-cell-winner" : ""}">${cellInner(agg)}</td>`;
  }

  // ─── Render pivot table ──────────────────────────────────────────────
  function renderTable() {
    const r = run();
    const tests = r.tests.filter((t) => activeTests.has(t.name));
    const models = r.models.filter((m) =>
      modelFilter.trim() ? m.toLowerCase().includes(modelFilter.trim().toLowerCase()) : true
    );
    const sorted = sortModels(models);

    if (sorted.length === 0) {
      thead.innerHTML = "";
      tbody.innerHTML = "";
      noResults.classList.remove("hidden");
      return;
    }
    noResults.classList.add("hidden");

    const arrow = (col) =>
      `<span class="sort-arrow">${sortCol === col ? (sortDir === "asc" ? "↑" : "↓") : "↕"}</span>`;

    let head = `<tr>
      <th class="bench-check-col"><input type="checkbox" id="w500SelectAll"></th>
      <th data-w500-sort="model" class="sortable">Model ${arrow("model")}</th>`;
    tests.forEach((t) => {
      head += `<th data-w500-sort="${esc(t.name)}" class="sortable">${esc(shortName(t.name))} ${arrow(
        t.name
      )}</th>`;
    });
    head += `<th data-w500-sort="${OVERALL}" class="sortable">Overall ${arrow(
      OVERALL
    )}<div class="w500-test-kind">all tests</div></th></tr>`;
    thead.innerHTML = head;

    // Best accuracy per column (ties share the highlight)
    const columns = tests.map((t) => t.name).concat([OVERALL]);
    const winners = {};
    columns.forEach((col) => {
      const values = sorted
        .map((m) => metricValue(getAgg(m, col), "accuracy"))
        .filter((v) => v != null);
      winners[col] = new Set();
      if (values.length < 2) return;
      const best = Math.max(...values);
      sorted.forEach((m) => {
        if (metricValue(getAgg(m, col), "accuracy") === best) winners[col].add(m);
      });
    });

    tbody.innerHTML = sorted
      .map((model) => {
        const isSelected = selectedModels.has(model);
        let row = `<tr data-model="${esc(model)}">
          <td class="bench-check-col"><input type="checkbox" class="w500-row-cb" data-model="${esc(model)}" ${
            isSelected ? "checked" : ""
          }></td>
          <td class="bench-model-name"><a href="#" class="w500-model-link" data-model="${esc(
            model
          )}">${esc(model)}</a></td>`;
        columns.forEach((col) => {
          row += cellHtml(getAgg(model, col), winners[col].has(model));
        });
        row += `</tr>`;
        return row;
      })
      .join("");

    thead.querySelectorAll(".sortable").forEach((th) => {
      th.addEventListener("click", () => {
        const col = th.dataset.w500Sort;
        if (sortCol === col) {
          sortDir = sortDir === "asc" ? "desc" : "asc";
        } else {
          sortCol = col;
          sortDir = defaultDirFor(col);
        }
        renderTable();
      });
    });

    updateCompareBtn();
    updateSelectAllState();
  }
  // ─── Select-All helper ───────────────────────────────────────────────
  function updateSelectAllState() {
    const cb = document.getElementById("w500SelectAll");
    if (!cb) return;
    const tableModels = [...tbody.querySelectorAll(".w500-model-link")].map(
      (a) => a.dataset.model
    );
    if (tableModels.length === 0) {
      cb.checked = false;
      cb.indeterminate = false;
      return;
    }
    const firstN = tableModels.slice(0, MAX_COMPARE);
    const selectedCount = firstN.filter((m) => selectedModels.has(m)).length;
    cb.checked = selectedCount === firstN.length && selectedCount > 0;
    cb.indeterminate = selectedCount > 0 && selectedCount < firstN.length;
  }

  // ─── Checkbox delegation ─────────────────────────────────────────────
  tbody.addEventListener("change", (e) => {
    if (e.target.classList.contains("w500-row-cb")) {
      const model = e.target.dataset.model;
      if (e.target.checked) {
        if (selectedModels.size >= MAX_COMPARE) {
          e.target.checked = false;
          return;
        }
        selectedModels.add(model);
      } else {
        selectedModels.delete(model);
      }
      updateCompareBtn();
      updateSelectAllState();
    }
  });

  document.addEventListener("change", (e) => {
    if (e.target.id !== "w500SelectAll") return;
    const tableModels = [...tbody.querySelectorAll(".w500-model-link")].map(
      (a) => a.dataset.model
    );
    const firstN = tableModels.slice(0, MAX_COMPARE);
    const allSelected = firstN.length > 0 && firstN.every((m) => selectedModels.has(m));
    if (allSelected) {
      firstN.forEach((m) => selectedModels.delete(m));
    } else {
      selectedModels.clear();
      firstN.forEach((m) => selectedModels.add(m));
    }
    renderTable();
    updateCompareBtn();
  });

  // ─── Compare mode ────────────────────────────────────────────────────
  function updateCompareBtn() {
    compareBtn.textContent = `Compare Selected (${selectedModels.size}/${MAX_COMPARE})`;
    compareBtn.disabled = selectedModels.size < 2;
  }

  compareBtn.addEventListener("click", () => {
    if (selectedModels.size < 2) return;
    enterCompareMode();
  });

  backBtn.addEventListener("click", exitCompareMode);

  function enterCompareMode() {
    compareMode = true;
    tableView.classList.add("hidden");
    compareView.classList.remove("hidden");
    compareBtn.classList.add("hidden");
    backBtn.classList.remove("hidden");
    modelInput.classList.add("hidden");
    renderCompare();
    renderCharts();
  }

  function exitCompareMode() {
    compareMode = false;
    compareView.classList.add("hidden");
    tableView.classList.remove("hidden");
    compareBtn.classList.remove("hidden");
    backBtn.classList.add("hidden");
    modelInput.classList.remove("hidden");
    destroyCharts();
  }

  function destroyCharts() {
    if (accChart) {
      accChart.destroy();
      accChart = null;
    }
    if (tokChart) {
      tokChart.destroy();
      tokChart = null;
    }
  }

  // ─── Compare view ────────────────────────────────────────────────────
  function renderCompare() {
    const r = run();
    const models = [...selectedModels].sort();
    const tests = r.tests.filter((t) => activeTests.has(t.name));

    compareModelsDiv.innerHTML = models
      .map(
        (m) =>
          `<span class="bench-model-chip">${esc(m)} <button class="bench-chip-remove" data-model="${esc(m)}">&times;</button></span>`
      )
      .join("");
    compareModelsDiv.querySelectorAll(".bench-chip-remove").forEach((btn) => {
      btn.addEventListener("click", () => {
        selectedModels.delete(btn.dataset.model);
        if (selectedModels.size < 2) {
          exitCompareMode();
          return;
        }
        renderCompare();
        renderCharts();
      });
    });

    const rows = tests
      .map((t) => ({ name: t.name, kind: null, samples: t.samples }))
      .concat([{ name: "Overall", kind: "all tests", samples: null }]);

    compareHead.innerHTML = `<tr><th>Test</th><th>Samples</th>${models
      .map((m) => `<th>${esc(m)}</th>`)
      .join("")}</tr>`;

    compareBody.innerHTML = rows
      .map((row) => {
        const colKey = row.name === "Overall" ? OVERALL : row.name;
        const aggs = models.map((m) => getAgg(m, colKey));
        const valid = aggs.filter((a) => a && a.n);
        const best = valid.length > 1 ? Math.max(...valid.map((a) => a.correct / a.n)) : null;
        const cells = aggs
          .map((a) => {
            if (!a || !a.n) return '<td class="bench-no-data">—</td>';
            const isWinner = best != null && a.correct / a.n === best;
            return `<td class="w500-cmp-cell${isWinner ? " w500-cmp-winner" : ""}">${cellInner(
              a
            )}</td>`;
          })
          .join("");
        const samplesLabel =
          row.samples != null
            ? "n=" + row.samples
            : aggs[0] && aggs[0].n
              ? "n=" + aggs[0].n
              : "—";
        return (
          `<tr><td>${esc(shortName(row.name))}${
            row.kind ? `<div class="w500-test-kind">${row.kind}</div>` : ""
          }</td>` +
          `<td>${samplesLabel}</td>${cells}</tr>`
        );
      })
      .join("");
  }

  // ─── Charts ──────────────────────────────────────────────────────────
  const PALETTE = [
    "#7c5cfc", "#ff6b9c", "#5cfcbc", "#ffc65c", "#5cff8c",
    "#ff5c5c", "#c65cff", "#5cffc6", "#ff8c5c", "#8cff5c",
  ];
  const CHART_FONT = "Inter, sans-serif";
  const TICK_COLOR = "#9898a8";
  const GRID_COLOR = "rgba(42,42,58,0.5)";

  function renderCharts() {
    const r = run();
    const models = [...selectedModels].sort();
    const tests = r.tests.filter((t) => activeTests.has(t.name));
    destroyCharts();
    if (tests.length === 0 || models.length === 0) return;
    const labels = tests.map((t) => shortName(t.name));

    const makeDatasets = (valueFn) =>
      models.map((m, i) => ({
        label: m,
        data: tests.map((t) => {
          const a = getAgg(m, t.name);
          return a && a.n ? valueFn(a) : null;
        }),
        backgroundColor: PALETTE[i % PALETTE.length],
        borderColor: PALETTE[i % PALETTE.length],
        borderWidth: 1,
        borderRadius: 4,
      }));

    const baseOptions = (yOpts, labelFn) => ({
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: { labels: { color: "#e8e8f0", font: { family: CHART_FONT } } },
        tooltip: { callbacks: { label: labelFn } },
      },
      scales: {
        x: {
          ticks: { color: TICK_COLOR, font: { family: CHART_FONT } },
          grid: { color: GRID_COLOR },
        },
        y: yOpts,
      },
    });

    accChart = new Chart(document.getElementById("w500ChartAccuracy").getContext("2d"), {
      type: "bar",
      data: { labels, datasets: makeDatasets((a) => (a.correct / a.n) * 100) },
      options: baseOptions(
        {
          beginAtZero: true,
          max: 100,
          ticks: {
            color: TICK_COLOR,
            font: { family: CHART_FONT },
            callback: (v) => v + "%",
          },
          grid: { color: GRID_COLOR },
        },
        (ctx) =>
          ctx.parsed.y !== null
            ? `${ctx.dataset.label}: ${ctx.parsed.y.toFixed(1)}%`
            : null
      ),
    });

    tokChart = new Chart(document.getElementById("w500ChartTokens").getContext("2d"), {
      type: "bar",
      data: { labels, datasets: makeDatasets((a) => a.tokens.avg) },
      options: baseOptions(
        {
          beginAtZero: true,
          ticks: {
            color: TICK_COLOR,
            font: { family: CHART_FONT },
            callback: (v) => fmtTok(v),
          },
          grid: { color: GRID_COLOR },
        },
        (ctx) =>
          ctx.parsed.y !== null
            ? `${ctx.dataset.label}: ${Math.round(ctx.parsed.y).toLocaleString("en-US")} tok`
            : null
      ),
    });
  }

  // ─── Model detail modal ──────────────────────────────────────────────
  function statusBadge(s) {
    const map = {
      stop: ["w500-status-stop", "stop"],
      "loop-abort": ["w500-status-loop", "loop abort"],
      "token-limit": ["w500-status-trunc", "token limit"],
      error: ["w500-status-err", "error"],
    };
    const [cls, label] = map[s] || ["", s || "—"];
    return `<span class="w500-status ${cls}">${esc(label)}</span>`;
  }

  function openModelModal(modelName) {
    // The model's source run (newest run wins) — its header shows where
    // the results came from.
    const r = modelRun[modelName];
    const m = r && r.results[modelName];
    if (!m) return;
    modalTitle.textContent = modelName;

    const cfg = r.config || {};
    let html =
      `<div class="bench-model-notes-box"><strong>Run ${esc(r.run_id)}</strong><p>` +
      `${fmtDate(r.created_at)} · ${m.overall.n} samples · max tokens ${fmtTok(cfg.max_tokens)}` +
      (cfg.loop_abort ? ` · loop abort after ${cfg.loop_abort_repeats} repeats` : "") +
      `</p></div>`;

    const summaryRow = (label, a, strong) => {
      if (!a || !a.n)
        return `<tr${strong ? ' class="w500-overall-row"' : ""}><td>${esc(label)}</td><td colspan="7" class="bench-no-data">—</td></tr>`;
      return (
        `<tr${strong ? ' class="w500-overall-row"' : ""}>` +
        `<td>${esc(label)}</td>` +
        `<td>${a.correct}/${a.n}</td>` +
        `<td>${fmtPct(a.correct / a.n)}</td>` +
        `<td>${a.tokens.estimated > 0 ? "≈ " : ""}${fmtTok(a.tokens.avg)}</td>` +
        `<td>${fmtTok(a.tokens.median)}</td>` +
        `<td>${a.truncated > 0 ? a.truncated : "—"}</td>` +
        `<td>${a.loop_aborts > 0 ? a.loop_aborts : "—"}</td>` +
        `<td>${fmtLat(a.latency_avg)}</td>` +
        `</tr>`
      );
    };

    html += `<table class="bench-detail-table">
      <thead><tr><th>Test</th><th>Correct</th><th>Accuracy</th><th>Avg tok</th><th>Median tok</th><th>Trunc</th><th>Loops</th><th>Avg time</th></tr></thead>
      <tbody>`;
    r.tests.forEach((t) => {
      html += summaryRow(shortName(t.name), m.tests[t.name]);
    });
    html += summaryRow("Overall", m.overall, true);
    html += `</tbody></table>`;

    // Per-sample detail
    r.tests.forEach((t) => {
      const entry = m.tests[t.name];
      if (!entry || !entry.samples || entry.samples.length === 0) return;
      html += `<h4 class="w500-modal-test">${esc(shortName(t.name))}</h4>`;
      html += `<table class="bench-subset-table">
        <thead><tr><th>#</th><th>Guess</th><th>Answer</th><th>Result</th><th>Tokens</th><th>Thinking (ch)</th><th>Time</th><th>Status</th></tr></thead>
        <tbody>`;
      entry.samples.forEach((s) => {
        html +=
          `<tr>` +
          `<td>${s.sample}</td>` +
          `<td>${s.guess ? esc(s.guess) : "—"}</td>` +
          `<td>${s.answer ? esc(s.answer) : "—"}</td>` +
          `<td><span class="${s.correct ? "w500-result-ok" : "w500-result-bad"}">${
            s.correct ? "✓" : "✗"
          }</span>${s.format_ok ? "" : '<span class="w500-fmt-bad" title="Malformed or missing final answer"> fmt</span>'}</td>` +
          `<td>${s.est ? "≈ " : ""}${fmtTok(s.tokens)}</td>` +
          `<td>${s.thinking != null ? fmtTok(s.thinking) : "—"}</td>` +
          `<td>${fmtLat(s.latency)}</td>` +
          `<td>${statusBadge(s.status)}</td>` +
          `</tr>`;
      });
      html += `</tbody></table>`;
    });

    modalBody.innerHTML = html;
    modal.classList.remove("hidden");
  }

  // ─── Model links & modal wiring ──────────────────────────────────────
  tbody.addEventListener("click", (e) => {
    const link = e.target.closest(".w500-model-link");
    if (link) {
      e.preventDefault();
      openModelModal(link.dataset.model);
    }
  });

  modalClose.addEventListener("click", () => modal.classList.add("hidden"));
  modal.addEventListener("click", (e) => {
    if (e.target === modal) modal.classList.add("hidden");
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && !modal.classList.contains("hidden"))
      modal.classList.add("hidden");
  });

  // ─── Init ────────────────────────────────────────────────────────────
  function renderAll() {
    renderRunBar();
    renderTestFilters();
    renderTable();
  }
  renderAll();
})();

